<?php session_start();if(!isset($_SESSION['user_id'])){header('Location: login.php');exit;}require_once 'includes/header.php'; ?>
<section class="page-shell narrow"><span class="eyebrow dark">MY PROFILE</span><h1>Account details</h1><div class="profile-card"><div class="avatar"><?php echo strtoupper(substr($_SESSION['user_name']??'U',0,1)); ?></div><form id="profileForm" class="profile-form"><div id="msg"></div><label>Full name<input id="name" value="<?php echo htmlspecialchars($_SESSION['user_name']??''); ?>" required></label><label>Email address<input id="email" type="email" value="<?php echo htmlspecialchars($_SESSION['user_email']??''); ?>" required></label><label>Phone number<input id="phone" placeholder="Add phone number"></label><label>Driving licence number<input id="license" placeholder="Add licence number"></label><button class="btn">Save profile</button></form></div></section>
<script>async function loadProfile(){const r=await fetch('api/auth/profile-details.php',{credentials:'include'}),j=await r.json();if(j.success){name.value=j.data.name||'';email.value=j.data.email||'';phone.value=j.data.phone||'';license.value=j.data.license||''}}profileForm.onsubmit=async e=>{e.preventDefault();const r=await fetch('api/auth/profile-details.php',{method:'PUT',headers:{'Content-Type':'application/json'},credentials:'include',body:JSON.stringify({name:name.value,email:email.value,phone:phone.value,license:license.value})}),j=await r.json();msg.innerHTML=`<div class="message ${j.success?'success':'error'}">${j.message}</div>`};loadProfile()</script>
<?php require_once 'includes/footer.php'; ?>
